using MediatR; using TopLab.Application.Common.Interfaces; using TopLab.Application.Common.Results; using TopLab.Domain.Common.Enums; using TopLab.Domain.Common.Ids; using TopLab.Domain.Patients; using TopLab.Domain.Results; using TopLab.Domain.Tests;
namespace TopLab.Application.Features.CultureResults.Commands.SaveCultureResults;
public sealed class SaveCultureResultsCommandHandler : IRequestHandler<SaveCultureResultsCommand, Result>
{ private readonly IApplicationDbContext _db; public SaveCultureResultsCommandHandler(IApplicationDbContext db) => _db = db;
 public async Task<Result> Handle(SaveCultureResultsCommand r, CancellationToken ct) { var pt=_db.Set<PatientTest>().FirstOrDefault(x=>x.Id.Value==r.PatientTestId); if(pt is null)return Result.Failure(Error.NotFound("التحليل غير موجود")); var test=_db.Set<Test>().FirstOrDefault(x=>x.Id.Value==pt.TestId.Value); if(test is null||!test.IsCultureType)return Result.Failure(Error.Conflict("هذا التحليل ليس من نوع المزارع.")); var patient=_db.Set<Patient>().FirstOrDefault(x=>x.Id.Value==pt.PatientId.Value); if(patient is null||patient.IsDeleted)return Result.Failure(Error.NotFound("المريض غير موجود.")); if(pt.IsReviewed||pt.IsPrinted||pt.IsDelivered)return Result.Failure(Error.Conflict("لا يمكن تعديل نتيجة مزرعة معتمدة أو مطبوعة أو مسلمة.")); var allowed=_db.Set<CultureAntibioticAttachment>().Where(x=>x.TestId.Value==test.Id.Value).Select(x=>x.AntibioticId.Value).ToHashSet(); if((r.Sensitivities??[]).Any(x=>!allowed.Contains(x.AntibioticId)))return Result.Failure(Error.Conflict("المضاد الحيوي غير مرفق بهذه المزرعة.")); var header=_db.Set<CultureResult>().FirstOrDefault(x=>x.PatientTestId.Value==pt.Id.Value); if(header is null){header=new CultureResult(pt.Id,r.Sample,r.OrganismA,r.OrganismB,r.OrganismC,r.CultureCondition,r.ColonyCount);_db.Add(header);}else header.Update(r.Sample,r.OrganismA,r.OrganismB,r.OrganismC,r.CultureCondition,r.ColonyCount); foreach(var old in _db.Set<CultureAntibioticResult>().Where(x=>x.PatientTestId.Value==pt.Id.Value).ToList())_db.Remove(old); foreach(var item in r.Sensitivities??[])_db.Add(CultureAntibioticResult.Create(CultureAntibioticResultId.Create(0),pt.Id,AntibioticId.Create(item.AntibioticId),(SensitivityCategory)item.SensitivityCategory)); await _db.SaveChangesAsync(ct); return Result.Success(); } }
